namespace ApexHUD.Native.Common;

/// <summary>
/// 2026-10-29 (car parity, phase 2 - "every Sports Car works like the BMWs"): one sourced fact sheet per car on
/// iRacing's Sports Car and Prototypes menus (91 cars, <c>CarCatalog.Data.cs</c>, generated by
/// <c>tools/car_catalog/gen_catalog.py</c>). Found by iRacing's CarID first (known for all 91), then the CarPath
/// (only the 59 verified ones are listed). A car that isn't here keeps the old behaviour (first-word maker,
/// car-name class guess). Every field that wasn't verified is null / 0 / empty, and Grandstand then shows nothing
/// for it (Angelo: "never show made-up numbers").
/// </summary>
public static partial class CarCatalog
{
    /// <param name="CarId">iRacing CarID (DriverInfo.Drivers[].CarID).</param>
    /// <param name="CarPath">iRacing CarPath, only when verified (Lovely Car Data's carId); else null.</param>
    /// <param name="Name">The car's name (fallback when iRacing's CarScreenName is empty).</param>
    /// <param name="ClassLabel">Grandstand's class label (GTP, LMP2, GT3, GT4, TCR, CUP, ...).</param>
    /// <param name="LogoSlug">A maker logo in assets/logos/manufacturers (no file is ever drawn by us), or null.</param>
    /// <param name="Maker">The maker as text, for cards when there is no logo.</param>
    /// <param name="Hybrid">true / false only when a source says so.</param>
    /// <param name="Electric">Fully electric (iRacing's car page).</param>
    /// <param name="Abs">The car has ABS (sourced), null = unknown (the live dcABS check decides).</param>
    /// <param name="Tc">The car has traction control (sourced), null = unknown (the live dcTractionControl check decides).</param>
    /// <param name="Gears">Forward gears when verified, else 0.</param>
    /// <param name="ShiftRpm">Shift-light (blink) rpm for gear 1, 2, ... from Lovely Car Data; empty = not known.</param>
    /// <param name="Story">One line from the car's iRacing page.</param>
    public sealed record CarInfo(int CarId, string? CarPath, string Name, string ClassLabel, string? LogoSlug, string? Maker,
                                 bool? Hybrid, bool Electric, bool? Abs, bool? Tc, int Gears, int[] ShiftRpm, string? Story)
    {
        /// <summary>The shift-light rpm for this gear (0 = not known; neutral / reverse use first gear's).</summary>
        public float ShiftFor(int gear)
        {
            if (ShiftRpm.Length == 0) return 0f;
            int g = Math.Clamp(gear, 1, ShiftRpm.Length);
            return ShiftRpm[g - 1];
        }
    }

    // built on first use: field initialisers in the two partial files run in no set order, so these must not
    // read All while the type is still initialising
    static Dictionary<int, CarInfo>? byId;
    static Dictionary<string, CarInfo>? byPath;
    static Dictionary<int, CarInfo> ById => byId ??= All.ToDictionary(c => c.CarId);
    static Dictionary<string, CarInfo> ByPath => byPath ??= All.Where(c => c.CarPath != null)
        .ToDictionary(c => c.CarPath!, StringComparer.OrdinalIgnoreCase);

    /// <summary>All the cars in the catalog.</summary>
    public static IReadOnlyList<CarInfo> Cars => All;

    /// <summary>The car by iRacing CarID, then by CarPath; null when it isn't one of the 91.</summary>
    public static CarInfo? Find(int carId, string? carPath)
    {
        if (carId > 0 && ById.TryGetValue(carId, out var byId))
        {
            // an id clash with a different verified path would mean the list is out of date - trust the path then
            if (byId.CarPath == null || string.IsNullOrEmpty(carPath) || string.Equals(byId.CarPath, carPath, StringComparison.OrdinalIgnoreCase))
                return byId;
        }
        if (!string.IsNullOrEmpty(carPath) && ByPath.TryGetValue(carPath.Trim(), out var byPath)) return byPath;
        return null;
    }

    /// <summary>The car on a leaderboard row.</summary>
    public static CarInfo? For(Driver? d) => d == null ? null : Find(d.CarId, d.CarPath);
}
